import{_ as t,o as s,c as o,ao as a}from"./chunks/framework.D7TN4pt9.js";const g=JSON.parse('{"title":"Configuration Files","description":"","frontmatter":{},"headers":[],"relativePath":"ref/config.md","filePath":"ref/config.md","lastUpdated":null}'),i={name:"ref/config.md"};function n(d,e,l,r,h,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="Configuration-Files" tabindex="-1">Configuration Files <a class="header-anchor" href="#Configuration-Files" aria-label="Permalink to &quot;Configuration Files {#Configuration-Files}&quot;">​</a></h1><p><code>settings.toml</code> holds the frontend&#39;s settings (layout, font, terminal and the rest); the frontend reads it when it starts. <code>hosts.toml</code> declares the hosts and is read by <code>sotd</code>; the window also reads it for the hub&#39;s name and for whether this box owns updates, but its connections come only from <code>--dial</code> flags. Chords live in a third file, <code>keybindings.toml</code>, described on its own page: <a href="./keybindings">Keybindings</a>. A missing or unparseable value keeps its default, an out-of-range <code>font.scale</code> is ignored, <code>drawer_height</code> is clamped, and no setting can crash the window.</p><h2 id="config-file-locations" tabindex="-1">Where the files are <a class="header-anchor" href="#config-file-locations" aria-label="Permalink to &quot;Where the files are {#config-file-locations}&quot;">​</a></h2><p>The window and <code>sotd</code> do not look in the same places.</p><ul><li><p><strong>The window</strong> reads <code>settings.toml</code> and <code>keybindings.toml</code> from the first of: <code>$SOT_SETTINGS</code> (or <code>$SOT_KEYBINDINGS</code>); <code>.sot/&lt;file&gt;</code> found by walking upward from the window&#39;s working directory; <code>$HOME/.config/sot/&lt;file&gt;</code>. It never consults <code>XDG_CONFIG_HOME</code>, and where <code>HOME</code> is unset (a normal Windows login) the last step finds nothing. On Windows the launcher sets <code>$SOT_SETTINGS</code> to the clone&#39;s <code>.sot\\settings.toml</code>.</p></li><li><p><strong><code>sotd</code></strong> reads <code>hosts.toml</code> (unless <code>$SOT_HOSTS</code> names a file) and the <code>[trust]</code> table of <code>settings.toml</code> from its config directory: <code>$XDG_CONFIG_HOME/sot</code> when that is set, else <code>~/.config/sot</code>; on Windows <code>%LOCALAPPDATA%\\sot\\config</code>.</p></li></ul><p>So on Linux and macOS with <code>XDG_CONFIG_HOME</code> set, the daemon&#39;s <code>settings.toml</code> is not the window&#39;s. On Windows they are two files: set <code>[trust] root_prefix</code> in the daemon&#39;s, not in the clone-local file the window reads.</p><h2 id="settings.toml" tabindex="-1"><code>settings.toml</code> <a class="header-anchor" href="#settings.toml" aria-label="Permalink to &quot;\`settings.toml\` {#settings.toml}&quot;">​</a></h2><p>Frontend settings.</p><h3 id="Discovery-order" tabindex="-1">Discovery order <a class="header-anchor" href="#Discovery-order" aria-label="Permalink to &quot;Discovery order {#Discovery-order}&quot;">​</a></h3><ol><li><p><code>$SOT_SETTINGS</code> — explicit path override.</p></li><li><p><code>.sot/settings.toml</code>, found by walking upward from the frontend&#39;s working directory (not the session&#39;s project).</p></li><li><p><code>$HOME/.config/sot/settings.toml</code> — per-user settings.</p></li><li><p>Built-in defaults.</p></li></ol><p>A value that is missing or does not parse keeps its default, and the reason is written to the window&#39;s log. A preset&#39;s <code>widths</code> has one entry per entry in its <code>columns</code>. When they do not match, a preset that sets its own <code>columns</code> keeps them and takes the built-in widths if their count fits, else splits the columns evenly; a <code>widths</code> with the wrong count and no <code>columns</code> of its own falls back to the built-in layout. Each fallback is named in a warning.</p><h3 id="layout" tabindex="-1"><code>[layout]</code> <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;\`[layout]\` {#layout}&quot;">​</a></h3><p>Layout is <strong>preset-based</strong>, keyed by the primary monitor&#39;s aspect ratio — there is no in-session reflow. The top-level <code>[layout]</code> table selects the active preset; three sub-tables define the presets.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Values</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>preset</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><code>auto</code> · <code>ultrawide</code> · <code>laptop</code> · <code>portrait</code></td><td style="text-align:right;"><code>auto</code></td><td style="text-align:right;">Which preset to use. <code>auto</code> resolves by the primary monitor&#39;s aspect ratio at startup (<code>&gt; 1.9</code> → ultrawide, <code>1.5–1.9</code> → laptop, <code>&lt; 1.5</code> → portrait); the other three lock to that preset regardless of aspect.</td></tr></tbody></table><h4 id="layout.ultrawide-/-layout.laptop-/-layout.portrait" tabindex="-1"><code>[layout.ultrawide]</code> / <code>[layout.laptop]</code> / <code>[layout.portrait]</code> <a class="header-anchor" href="#layout.ultrawide-/-layout.laptop-/-layout.portrait" aria-label="Permalink to &quot;\`[layout.ultrawide]\` / \`[layout.laptop]\` / \`[layout.portrait]\` {#layout.ultrawide-/-layout.laptop-/-layout.portrait}&quot;">​</a></h4><p>One sub-table per aspect bucket, each defining its columns, their widths, and the shared bottom drawer.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default (ultrawide)</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>columns</code></td><td style="text-align:right;">comma-list of slot names (<code>nav</code> · <code>preview</code> · <code>llm</code> · <code>repl</code>)</td><td style="text-align:right;"><code>nav,preview,llm</code></td><td style="text-align:right;">Named column slots, left to right.</td></tr><tr><td style="text-align:right;"><code>widths</code></td><td style="text-align:right;">comma-list of fractions</td><td style="text-align:right;"><code>0.167,0.333,0.5</code></td><td style="text-align:right;">Fractional column widths, one per column; renormalized to sum to 1.0 on parse. A count that differs from <code>columns</code> warns and gives the columns an equal split.</td></tr><tr><td style="text-align:right;"><code>drawer</code></td><td style="text-align:right;">slot name or <code>none</code></td><td style="text-align:right;"><code>repl</code></td><td style="text-align:right;">Slot rendered in the shared bottom drawer when toggled open.</td></tr><tr><td style="text-align:right;"><code>drawer_height</code></td><td style="text-align:right;">fraction <code>[0.10, 0.80]</code></td><td style="text-align:right;"><code>0.35</code></td><td style="text-align:right;">Drawer height as a fraction of window height when open; clamped to range.</td></tr></tbody></table><p>Laptop defaults to <code>0.18,0.32,0.50</code> widths with a <code>0.40</code> drawer; portrait drops the <code>llm</code> column (<code>nav,preview</code> at <code>0.30,0.70</code>, <code>0.40</code> drawer). Unknown keys are ignored with a logged warning, and a value that does not parse keeps the default.</p><h3 id="Other-sections" tabindex="-1">Other sections <a class="header-anchor" href="#Other-sections" aria-label="Permalink to &quot;Other sections {#Other-sections}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Section / key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>[terminal] shell</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><em>(auto)</em></td><td style="text-align:right;">Shell the Terminal drawer spawns. Unset resolves per platform: <code>$SHELL</code>, then <code>/bin/bash</code>, <code>/bin/sh</code> on Unix; <code>pwsh.exe</code>, <code>powershell.exe</code>, <code>cmd.exe</code> on Windows.</td></tr><tr><td style="text-align:right;"><code>[repl] auto_open_drawer_on_run</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>true</code></td><td style="text-align:right;">Running a <code>.jl</code> file from the navigation tree with <code>r</code>/<code>R</code> opens the REPL drawer if it is closed, so the run&#39;s output is visible. Navigation keeps focus.</td></tr><tr><td style="text-align:right;"><code>[font] scale</code></td><td style="text-align:right;">number <code>[0.5, 3.0]</code></td><td style="text-align:right;"><em>(by monitor width)</em></td><td style="text-align:right;">Text-size multiplier at startup. A zoom you saved with the font-scale keys wins over this key, and <code>--font-scale</code> on the command line overrides both. Unset, wide monitors start with larger text.</td></tr><tr><td style="text-align:right;"><code>[nav] spill_ms</code></td><td style="text-align:right;">integer, ms</td><td style="text-align:right;"><code>2000</code></td><td style="text-align:right;">While the navigation cursor is moving, a row too long for the column floats its full text over the preview pane&#39;s left edge, and the text vanishes this many milliseconds after the last move. <code>0</code> turns it off.</td></tr><tr><td style="text-align:right;"><code>[trust] root_prefix</code></td><td style="text-align:right;">absolute path</td><td style="text-align:right;"><em>(none)</em></td><td style="text-align:right;">Read by the daemon from its own <code>settings.toml</code> (see <a href="/ship-of-tools/stable/ref/config#config-file-locations">Where the files are</a>); the frontend ignores it. When it starts an agent in a project folder under this prefix, it marks Claude Code&#39;s trust dialog for that folder as answered. Set it with <code>sotd trust declare &lt;absolute-prefix&gt;</code>.</td></tr><tr><td style="text-align:right;"><code>[downloads] dir</code></td><td style="text-align:right;">path</td><td style="text-align:right;"><em>(OS download dir)</em></td><td style="text-align:right;">Local directory <code>d</code> (download) writes to. Empty means the OS download directory.</td></tr><tr><td style="text-align:right;"><code>[sessions] new_session_root</code></td><td style="text-align:right;">path</td><td style="text-align:right;"><em>(fallback chain)</em></td><td style="text-align:right;">Backend-host directory the new-session picker starts browsing from. Unset falls back to <code>$SOT_PROJECTS_ROOT</code>. For a remote host the picker then tries <code>$SOT_REMOTE_HOME</code>, the daemon&#39;s default root, then the window&#39;s <code>$HOME</code>. For the local host the configured root counts only if it exists on this disk; otherwise the picker starts at the daemon&#39;s default root, then <code>$HOME</code>.</td></tr><tr><td style="text-align:right;"><code>[drawer] attach_only</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Windows only: the Terminal drawer attaches to a running capsule instead of spawning a local shell. Dormant: nothing starts a drawer capsule to attach to, so leave it <code>false</code>. Read when the drawer is created; takes a frontend restart.</td></tr></tbody></table><h3 id="gpu" tabindex="-1"><code>[gpu]</code> <a class="header-anchor" href="#gpu" aria-label="Permalink to &quot;\`[gpu]\` {#gpu}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Values</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>power_preference</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><code>low</code> · <code>high</code></td><td style="text-align:right;"><code>low</code></td><td style="text-align:right;">Which adapter to request from wgpu. <code>low</code> prefers the integrated GPU; <code>high</code> prefers the discrete one. wgpu&#39;s own spellings (<code>low_power</code>, <code>high_performance</code>) and <code>integrated</code>/<code>discrete</code> are accepted; case is ignored.</td></tr></tbody></table><p>The frontend renders glyph quads and image blits — a 2D workload an integrated GPU handles comfortably — so it asks for the <strong>low-power adapter by default</strong>. On a hybrid-graphics laptop, requesting the discrete GPU keeps it awake for the entire session: an active surface prevents the dGPU from power-gating. Set <code>high</code> if you are on a desktop with a real GPU, or if the integrated adapter renders incorrectly.</p><p>On single-adapter machines the key is a <strong>no-op</strong> — with only an integrated GPU present, <code>high</code> already resolves to it.</p><blockquote><p><strong>Takes effect on the next frontend start.</strong> The preference binds once, when the adapter and surface are created at startup, so editing this key mid-session changes nothing until the frontend restarts.</p></blockquote><h3 id="display" tabindex="-1"><code>[display]</code> <a class="header-anchor" href="#display" aria-label="Permalink to &quot;\`[display]\` {#display}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>fullscreen_vsync_pin</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">While fullscreen, keep requesting a redraw every vsync instead of falling back to the on-demand idle tick.</td></tr></tbody></table><p>In borderless fullscreen, DWM composition disengages and the panel&#39;s refresh follows the frontend&#39;s present cadence directly. The efficient on-demand idle path presents ~1 frame/sec, which drives a VRR/adaptive-sync OLED panel into the 1–10 Hz band where low-framerate compensation makes brightness pump visibly. With the pin on, fullscreen instead requests a redraw every vsync so the panel stays pinned at its native refresh; this costs continuous GPU while fullscreen.</p><p>There is no VRR/adaptive-sync detection API worth trusting, so this is a setting rather than a heuristic, and it defaults to <code>false</code>: most panels are fixed-refresh and the pin only burns power for no visible benefit. Set <code>true</code> on a VRR/adaptive-sync OLED panel that pumps brightness in borderless fullscreen.</p><h3 id="Example" tabindex="-1">Example <a class="header-anchor" href="#Example" aria-label="Permalink to &quot;Example {#Example}&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">layout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">preset = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # auto | ultrawide | laptop | portrait</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">layout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ultrawide</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># primary monitor aspect &gt; 1.9</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">columns       = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nav,preview,llm&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">widths        = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.167,0.333,0.5&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drawer        = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;repl&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drawer_height = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.35&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">power_preference = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;low&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # low (integrated, default) | high (discrete)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fullscreen_vsync_pin = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # default false | true on a VRR/OLED panel</span></span></code></pre></div><h2 id="hosts.toml" tabindex="-1"><code>hosts.toml</code> <a class="header-anchor" href="#hosts.toml" aria-label="Permalink to &quot;\`hosts.toml\` {#hosts.toml}&quot;">​</a></h2><p>The declared topology: which host is the relay hub, which hosts run a daemon, which run a frontend, and which hosts the Monitor drawer (<code>drawer.monitor</code>) samples. <code>sot_protocol::topology</code> (Rust) is the <strong>one parser</strong> for this file — <code>sotd</code> and the window call it, and the launchers get their facts only from <code>sotd topology plan|status|sync|relay-endpoint</code>. The PowerShell launcher does not parse <code>hosts.toml</code> itself: it runs <code>sotd topology plan --self &lt;host&gt;</code> and renders its plain-line output into <code>--dial &lt;host&gt;=&lt;endpoint&gt;</code> flags for the frontend (each an ssh child the frontend spawns itself, or a local socket/pipe). <code>sot --dial</code> takes one connection per flag and may repeat; <code>sot --help</code> lists it. The window does load <code>hosts.toml</code> through the same parser, but only for the hub&#39;s name (the Monitor drawer&#39;s subscription) and to decide whether this box owns updates; which daemons it connects to comes only from <code>--dial</code> (<code>rust/protocol/src/topology/mod.rs</code>&#39;s <code>plan</code> doc comment has the exact line-oriented contract).</p><p>The format is deliberately simple — a section per host, scalar <code>key = value</code> lines — so it needs no TOML library.</p><h3 id="Discovery-order-2" tabindex="-1">Discovery order <a class="header-anchor" href="#Discovery-order-2" aria-label="Permalink to &quot;Discovery order {#Discovery-order-2}&quot;">​</a></h3><p>The one search order, used everywhere this file is read:</p><ol><li><p><code>$SOT_HOSTS</code> — explicit path override (tests, scratch daemons).</p></li><li><p><code>&lt;config dir&gt;/hosts.toml</code> — <code>$XDG_CONFIG_HOME/sot/hosts.toml</code> when <code>XDG_CONFIG_HOME</code> is set, else <code>~/.config/sot/hosts.toml</code> on Linux/macOS; <code>%LOCALAPPDATA%\\sot\\config\\hosts.toml</code> on Windows.</p></li></ol><p>There is no repo-local <code>.sot/hosts.toml</code> layer: the hub&#39;s own copy is canonical, and every other box&#39;s copy is a <code>sotd topology sync --hub &lt;alias&gt;</code> fetch of it.</p><h3 id="Top-level" tabindex="-1">Top-level <a class="header-anchor" href="#Top-level" aria-label="Permalink to &quot;Top-level {#Top-level}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>hub</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><em>(required)</em></td><td style="text-align:right;">The one host running the relay daemon every other box&#39;s comm handles register on and dial through. Exactly one <code>hub</code> key, naming a listed host.</td></tr></tbody></table><h3 id="host.name" tabindex="-1"><code>[host.&lt;name&gt;]</code> <a class="header-anchor" href="#host.name" aria-label="Permalink to &quot;\`[host.&lt;name&gt;]\` {#host.name}&quot;">​</a></h3><p>One section per host. <code>&lt;name&gt;</code> is the plain host name (<code>[a-z0-9][a-z0-9._-]*</code>) that box&#39;s own <code>host_name()</code> resolves to — it doubles as its SSH alias. Every other box reaches a daemon host through an ssh child into the hub, so only the hub needs an <code>~/.ssh/config</code> entry for each daemon host, and every other box needs one for the hub.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>daemon</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">This host runs <code>sotd</code> and can be dialled. <code>sotd topology plan</code> emits a <code>dial</code> line for every daemon host: this box&#39;s own socket for itself, the hub&#39;s own relay socket for a remote host (on the hub only), and <code>ssh:&lt;hub&gt;</code> / <code>ssh:&lt;hub&gt;/&lt;host&gt;</code> everywhere else.</td></tr><tr><td style="text-align:right;"><code>frontend</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">This host runs a frontend and its launcher, and so its own private <code>sotd</code>.</td></tr></tbody></table><p>A host can be <code>daemon = true</code>, <code>frontend = true</code>, or both (a workstation running its own daemon <em>and</em> driving a local frontend). A host declared with neither runs no <code>sotd</code>: <code>sotd.service</code> is pinned only to hosts that declare <code>daemon</code> or <code>frontend</code>, and the updater arms nothing there. The hub itself needs <code>daemon = true</code> too — it is still a listed host, just the one every other daemon host&#39;s relay handles register on.</p><h3 id="File-watcher-budget" tabindex="-1">File-watcher budget <a class="header-anchor" href="#File-watcher-budget" aria-label="Permalink to &quot;File-watcher budget {#File-watcher-budget}&quot;">​</a></h3><p><code>sotd</code> watches each workspace&#39;s tree to refresh previews on disk changes, registering one (non-recursive) inotify watch per kept directory. It skips build/VCS directories and never crosses a filesystem boundary (so a project root over a mounted data share doesn&#39;t pull the share in), and it caps the watches per workspace at <code>min(8192, ¼ of fs.inotify.max_user_watches)</code> so it can&#39;t exhaust the OS watch table. Override the cap with <code>SOT_WATCH_BUDGET=&lt;n&gt;</code> in the backend environment. Past the cap, deeper subtrees stop auto-refreshing; navigation still refreshes previews reactively.</p><h3 id="monitor" tabindex="-1"><code>[monitor]</code> <a class="header-anchor" href="#monitor" aria-label="Permalink to &quot;\`[monitor]\` {#monitor}&quot;">​</a></h3><p>The hosts sampled for the Monitor drawer (<code>drawer.monitor</code>). <strong>Hub-scoped:</strong> declared once, but only the declared <code>hub</code> executes it — every non-hub daemon samples just the host it runs on, regardless of what this table says, so the roster&#39;s ssh aliases need only resolve <strong>on the hub</strong>. The drawer itself subscribes to the hub, not to whichever host the frontend happens to be navigating. Each line is <code>&lt;display-name&gt; = &quot;&lt;ssh-alias&gt;&quot;</code>. A monitor target is not a <code>[host.*]</code>: it can be any box you can reach with <code>ssh</code>, and it needs no section above.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Form</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>&lt;name&gt; = &quot;&lt;ssh-alias&gt;&quot;</code></td><td style="text-align:right;">Sample this host in the monitor drawer. The host whose name (or alias) matches the hub&#39;s hostname is sampled <strong>locally</strong> (no SSH); the rest are sampled over <code>ssh &lt;alias&gt;</code> from the hub.</td></tr></tbody></table><p><code>nvidia-smi</code> and <code>/proc</code> are world-readable, so no <code>sudo</code> or special privileges are needed on any monitored host. Remove a line to stop monitoring that host. The sampler reads <code>/proc</code>, so a daemon samples its own host only on Linux; on macOS and Windows the local host is left out of the drawer.</p><h3 id="Example-2" tabindex="-1">Example <a class="header-anchor" href="#Example-2" aria-label="Permalink to &quot;Example {#Example-2}&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hub = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myserver&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">daemon = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A frontend box.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">laptop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A second daemon host; its SSH alias on the hub is \`otherbox\`.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">otherbox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">daemon = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">myserver = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myserver&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">otherbox = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;otherbox&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host-c = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;host-c&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # sampled over ssh; not a [host.*] above</span></span></code></pre></div><p><code>sotd topology plan --self laptop</code> on the laptop above renders as (see <code>rust/protocol/src/topology/mod.rs</code>&#39;s <code>plan</code> doc comment for the exact grammar):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>self laptop</span></span>
<span class="line"><span>hub myserver</span></span>
<span class="line"><span>relay-endpoint ssh:myserver</span></span>
<span class="line"><span>dial myserver ssh:myserver</span></span>
<span class="line"><span>dial otherbox ssh:myserver/otherbox</span></span></code></pre></div><p>— which the launcher turns into <code>--dial myserver=ssh:myserver --dial otherbox=ssh:myserver/otherbox</code> for the frontend: an ssh child into the hub, no argument for the hub&#39;s own daemon and <code>--host otherbox</code> to reach the hub&#39;s relay socket for the other one. No port, no forward — read the actual endpoints from <code>sotd topology plan</code>, never hardcode one.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><a href="./keybindings">Keybindings</a> — chords and grammar; the file is found as <code>settings.toml</code> is: <code>$SOT_KEYBINDINGS</code>, then <code>.sot/keybindings.toml</code> up from the working directory, then <code>~/.config/sot/keybindings.toml</code>.</li></ul>`,57)])])}const y=t(i,[["render",n]]);export{g as __pageData,y as default};
